        // Defines the role sequence.
        InitInternalWorkflow();
        const currentRequester = Users.GetUser(Data.GetValue("OwnerId"));
        Variable.SetValueAsString("requesterShortLogin", Lib.P2P.GetShortLoginFromUser(currentRequester));
