}
function InitTableLineIds(tableCtrl, idFieldName) {
    if (tableCtrl && tableCtrl.GetRow(0)[idFieldName].GetValue() === null) {
        for (let i = 0; i < tableCtrl.GetItemCount(); i++) {
            tableCtrl.GetRow(i)[idFieldName].SetValue(i);
