																			],
																			"stamp": 126,
																			"options": {
																				"version": 0,
																				"lines": 1,
																				"columns": 2,
																				"ctrlsPos": {
																					"CreditScore_GaugeContainer__": {
																						"line": 1,
																						"column": 1
																					}
																				},
																				"colspans": [
